<span class="line"><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">        limit_req </span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">zone=my_rate_limit burst=20 nodelay;</span></span>
